<template><PageContainer><PageHeader eyebrow="SCR-MON-005" title="Incidents monitoring" description="Pilotage des incidents plateforme, de la detection a la mitigation."><template #actions><RouterLink class="mon-pill" to="/app/monitoring"><ArrowLeft/>Retour</RouterLink><button class="mon-btn mon-btn--primary" @click="store.chargerIncidents"><RefreshCw/>Actualiser</button></template></PageHeader><SectionBlock v-if="canOpen" title="Ouvrir un incident" description="Creation conforme au workflow MON-06."><form class="mon-grid" @submit.prevent="open"><label class="mon-field"><span>Identifiant</span><input v-model="form.incidentId" maxlength="160"/></label><label class="mon-field"><span>Niveau</span><select v-model="form.niveau"><option>DEGRADED</option><option>CRITICAL</option><option>UNKNOWN</option><option>HEALTHY</option></select></label><label class="mon-field mon-field--full"><span>Resume</span><textarea v-model="form.resume" maxlength="1000" rows="3"></textarea></label><label class="mon-field mon-field--full"><span>Correlation ID</span><input v-model="form.correlationId" maxlength="128"/></label><div class="mon-actions mon-field--full"><button class="mon-btn mon-btn--primary" type="submit">Ouvrir l'incident</button></div></form></SectionBlock><LoadingState v-if="store.state.status==='loading'" title="Incidents en cours" message="Actualisation des incidents plateforme."/><ErrorState v-else-if="store.state.status==='error'" title="Incidents indisponibles" :message="store.state.errorMessage??'Erreur technique.'"/><SectionBlock v-else title="Incidents" description="Incidents ouverts et recents."><MonitoringEmptyState v-if="!store.state.incidents.length" title="Aucun incident" message="La plateforme n'expose aucun incident."/><div v-else class="mon-table-wrap"><table class="mon-table"><thead><tr><th>Incident</th><th>Niveau</th><th>Statut</th><th>Debut</th><th>Alertes</th><th>Diagnostics</th><th>Action</th></tr></thead><tbody><tr v-for="i in store.state.incidents" :key="i.identifiant"><td><strong>{{i.identifiant}}</strong><div class="mon-muted">{{i.resume}}</div></td><td :class="`mon-level mon-level--${i.niveau}`">{{i.niveau}}</td><td>{{i.statut}}</td><td>{{date(i.detecteLe)}}</td><td>{{i.alertes.length}}</td><td>{{i.diagnostics.length}}</td><td><button v-if="canEscalate&&i.statut!=='RESOLVED'" class="mon-btn" @click="escalate(i.identifiant)">Escalader</button><span v-else class="mon-muted">Lecture</span></td></tr></tbody></table></div></SectionBlock></PageContainer></template>
<script setup lang="ts">import {reactive} from 'vue';import {RouterLink} from 'vue-router';import {ArrowLeft,RefreshCw} from 'lucide-vue-next';import PageContainer from '../../../shared/layout/PageContainer.vue';import PageHeader from '../../../shared/layout/PageHeader.vue';import SectionBlock from '../../../shared/layout/SectionBlock.vue';import LoadingState from '../../../shared/ui/LoadingState.vue';import ErrorState from '../../../shared/ui/ErrorState.vue';import MonitoringEmptyState from '../components/MonitoringEmptyState.vue';import {hasMonitoringPermission} from '../access/monitoring-access';import {required} from '../validation/monitoring-form.validation';import type {HealthLevel} from '../models/monitoring.model';import {useMonitoringStore} from '../stores/monitoring.store';import '../monitoring.css';const store=useMonitoringStore();const canOpen=hasMonitoringPermission('monitoring.incidents.create'),canEscalate=hasMonitoringPermission('monitoring.incidents.escalate');const form=reactive<{incidentId:string;resume:string;niveau:HealthLevel;correlationId:string}>({incidentId:'',resume:'',niveau:'DEGRADED',correlationId:''});async function open(){if(required(form.incidentId,'Identifiant')||required(form.resume,'Resume',1000)||required(form.correlationId,'Correlation ID',128))return;await store.ouvrirIncident({...form})}async function escalate(id:string){if(confirm('Confirmer l’escalade de cet incident ?'))await store.escaladerIncident(id)}const date=(v:string)=>new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v));</script>
